import java.util.*;

public class Main {
    static long modpow(long base, long exp, int MOD) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % MOD;
            base = (base * base) % MOD;
            exp >>= 1;
        }
        return result;
    }

    static class DSU {
        int[] parent;
        int[] rank;
        int components;

        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            components = n;
            for (int i = 0; i < n; i++) {
                parent[i] = i;
            }
        }

        int find(int u) {
            if (parent[u] != u) {
                parent[u] = find(parent[u]);
            }
            return parent[u];
        }

        void unite(int u, int v) {
            u = find(u);
            v = find(v);
            if (u != v) {
                if (rank[u] < rank[v]) {
                    int temp = u;
                    u = v;
                    v = temp;
                }
                parent[v] = u;
                if (rank[u] == rank[v]) {
                    rank[u]++;
                }
                components--;
            }
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long p = sc.nextLong();
        long k = sc.nextLong();
        boolean[] visited = new boolean[(int)p];
        DSU d = new DSU((int)p);
        for (long i = 0; i < p; i++) {
            long j = i;
            while (!visited[(int)j]) {
                visited[(int)j] = true;
                d.unite((int)i, (int)j);
                j = (j * k) % p;
            }
        }
        int c = d.components;
        if (k != 1) c--;
        System.out.println(modpow(p, c, 1000000007));
        sc.close();
    }
}
